<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Domain\Gateway;

use Civi\Lughauth\Features\Document\Rendering\Domain\RenderedTemplate;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateRenderRequest;

/**
 * Port for the template rendering engine.
 *
 * The implementation is responsible solely for the technical substitution of variables and
 * snippet partials into raw template content strings. All domain logic (template lookup, version
 * selection, variable resolution) is handled by the use case before calling this gateway.
 */
interface TemplateRenderGateway
{
    /**
     * Render a template from pre-resolved raw content and variables.
     *
     * @param TemplateRenderRequest $request Raw content strings, snippets map and merged variable map.
     * @return RenderedTemplate The rendered template with all placeholders substituted.
     */
    public function render(TemplateRenderRequest $request): RenderedTemplate;
}
